"""Vehicles (1.2.0): buying into the Garage with cyber controls, control rolls and the loss table, hits through
SP to structure, crashes, and vehicles in the GM's combat tracker."""
import asyncio, os
from playwright.async_api import async_playwright
from harness import *

SHOTS=os.path.join(OUT,"veh");os.makedirs(SHOTS,exist_ok=True)
RIG="window.__mr=window.__mr||Math.random;window.rig=l=>{const q=l.map(([n,v])=>(v-0.5)/n);Math.random=()=>{if(!/at d \\(/.test(new Error().stack))return window.__mr();return q.length?q.shift():0.45}};0"
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pl=await page(b,"P","player.html");pl.set_default_timeout(8000)
        await make_runner(pl,"Wheels")
        await pl.click(".card:has-text('Wheels') >> text=Open sheet");await pl.wait_for_timeout(300)
        await pl.evaluate(RIG);J=lambda s:pl.evaluate(s)
        await J("(()=>{const c=curChar();c.eb=100000;c.stats.REF=8;c.skills.Driving={c:4,p:0,b:0};saveChar(c,true);render()})()")
        ok(await J("VEHICLES.every(v=>VEH_CONTROL[v.kind]!==undefined&&SKILL_BY_NAME[v.skill])"),"every vehicle has a control row and a real skill")
        ok(await J("GEAR.filter(g=>g[2]==='Vehicles').every(g=>VEH_BY_NAME[g[0]])"),"every vehicle in the gear shop has stats")
        # the shop
        await pl.click("[data-act=tab][data-t=gear]");await pl.wait_for_timeout(100)
        ok("No wheels" in await pl.text_content(".garage"),"an empty Garage on the Gear & cash tab")
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Gear]");await pl.wait_for_timeout(200)
        ok("210 mph" in await pl.text_content(".shop-list"),"vehicle rows show their speed")
        i=await J("GEAR.findIndex(g=>g[0]==='Sportscar')")
        await pl.locator(f".shop-row[data-info='g:{i}']").hover();await pl.wait_for_timeout(300)
        ok("210 mph" in await pl.text_content("#shop-detail") and "Twice the price" in await pl.text_content("#shop-detail"),"the vehicle's card lists its numbers")
        await pl.check("[data-act-change=shop-vcyber]");await pl.wait_for_timeout(100)
        ok("40,000" in await pl.text_content(f".shop-row[data-info='g:{i}']"),"cyber controls show at twice the price")
        await pl.click(f"[data-act=buy][data-k=g][data-i='{i}']");await pl.wait_for_timeout(100)
        v=await J("curChar().vehicles[0]")
        ok(v and v["name"]=="Sportscar" and v["cyber"] and v["cost"]==40000 and await J("curChar().eb")==60000,"a cyber-controlled sportscar costs 40,000eb and goes to the Garage")
        ok(not await J("curChar().gear.some(g=>g.name==='Sportscar')"),"and not into the gear list")
        await pl.uncheck("[data-act-change=shop-vcyber]");m=await J("GEAR.findIndex(g=>g[0]==='Motorcycle')")
        await pl.click(f"[data-act=buy][data-k=g][data-i='{m}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().vehicles.length")==2 and await J("curChar().eb")==58500,"a plain motorcycle at 1,500eb")
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        ok(await pl.locator(".garage .veh").count()==2,"both are in the Garage")
        # control roll
        vid=v["id"]
        await pl.click(f"[data-act=veh-control][data-v='{vid}']");await pl.wait_for_timeout(150)
        t=await pl.text_content(".modal")
        ok("REF 8 + Driving 4 + Sportscar 2 = 14" in t,"REF + Driving + the sportscar's +2")
        await pl.click("[data-act=vc-set][data-k=dv][data-v='25']");await pl.click("[data-act=vc-set][data-k=speed][data-v='-4']");await pl.wait_for_timeout(80)
        ok("Triple safe speed -4" in await pl.text_content(".modal") or "Triple safe speed −4" in await pl.text_content(".modal"),"speed modifiers come off")
        await J("rig([[10,2],[6,5],[10,3]])");await pl.click("[data-act=vc-roll]");await pl.wait_for_timeout(150)
        t=await pl.text_content(".modal");lg=await J("Dice.log.slice(0,2).map(x=>x.label)")
        ok("Lost control" in t and "Control loss 5" in t and "Rolls after sliding 30 feet" in t,"a failed control roll rolls the Control Loss table %s"%lg)
        ok(await J("curChar().vehicles[0].sdpDmg")>0,"a rollover damages the vehicle (5D6)")
        await J("rig([[10,9]])");await pl.click("[data-act=vc-set][data-k=dv][data-v='15']");await pl.click("[data-act=vc-set][data-k=speed][data-v='0']");await pl.click("[data-act=vc-roll]");await pl.wait_for_timeout(120)
        ok("In control" in await pl.text_content(".modal"),"14 + 9 beats a Simple maneuver")
        await pl.screenshot(path=os.path.join(SHOTS,"control.png"));await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        # hits and crashes
        await J("(()=>{const c=curChar();c.vehicles[0].sdpDmg=0;c.vehicles[0].sp=20;saveChar(c,true);render()})()");await pl.wait_for_timeout(80)
        await pl.fill(f"#vh-{vid}","30");await pl.click(f"[data-act=veh-hit][data-v='{vid}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().vehicles[0].sdpDmg")==10,"30 damage against SP 20 does 10 structure")
        await pl.fill(f"#vh-{vid}","30");await pl.check(f"#vap-{vid}");await pl.click(f"[data-act=veh-hit][data-v='{vid}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().vehicles[0].sdpDmg")==30,"AP halves the vehicle's SP (30 − 10 = 20 more)")
        r=await J("(()=>{const v=curChar().vehicles[0];return vehCrash(v,100,3,'x')})()")
        ok(r["n"]==15 and r["half"]==7,"a crash at 100 mph into a car: 5D6 × 3 = 15D6, occupants 7D6")
        await pl.fill(f"#vs-{vid}","60");await pl.select_option(f"#vw-{vid}","1");await pl.click(f"[data-act=veh-crash][data-v='{vid}']");await pl.wait_for_timeout(100)
        ok("3D6" in await pl.text_content(".garage") and await J("curChar().vehicles[0].sdpDmg")>30,"the Crash button applies speed ÷ 20 dice")
        await J("(()=>{const c=curChar();c.vehicles[0].sdpDmg=50;saveChar(c,true);render()})()");await pl.wait_for_timeout(80)
        ok("Wrecked" in await pl.text_content(".garage") and await pl.locator(f"[data-act=veh-control][data-v='{vid}'][disabled]").count()==1,"a wreck at 0 SDP can't be driven")
        await pl.click(f"[data-act=veh-sdp][data-v='{vid}'][data-d=reset]");await pl.wait_for_timeout(80)
        ok(await J("curChar().vehicles[0].sdpDmg")==0,"Repaired clears the damage")
        await pl.screenshot(path=os.path.join(SHOTS,"garage.png"),full_page=True)
        # cyber controls + cables
        await J("(()=>{const c=curChar();c.gear.push({id:uid(),name:'Low impedance cables',qty:1,cost:60});saveChar(c,true)})()")
        ok(await J("vehControlParts(curChar(),curChar().vehicles[0],{}).some(p=>p[0]==='Low impedance cables')"),"low impedance cables add +1 on cyber controls")
        ok(not await J("vehControlParts(curChar(),curChar().vehicles[1],{}).some(p=>p[0]==='Low impedance cables')"),"but not on ordinary controls")
        # GM tracker
        gm=await page(b,"GM","gm.html");gm.set_default_timeout(8000);await gm.evaluate(RIG)
        await gm.evaluate("()=>{const c=normalizeChar({...clone(SAMPLE),id:'pc1',handle:'Ghost'});c.vehicles=[mkVehicle(VEH_BY_NAME['Medium sedan'])];st.party.push(c);persist();render()}")
        await gm.click("nav [data-act=tab][data-t=party]");await gm.wait_for_timeout(150);await gm.click("[data-act=open-pc][data-id=pc1] >> nth=0");await gm.wait_for_timeout(150)
        ok("Medium sedan" in await gm.text_content(".panel:has(h3:text('Garage'))"),"the GM sees the runner's garage")
        await gm.click("[data-act=close-pc]");await gm.click("nav [data-act=tab][data-t=encounter]");await gm.wait_for_timeout(150)
        await gm.click("[data-act=enc-add-party]");await gm.select_option("#enc-veh",str(await gm.evaluate("VEHICLES.findIndex(v=>v.name.startsWith('AV-4'))")));await gm.click("[data-act=enc-add-veh]");await gm.wait_for_timeout(150)
        vc=await gm.evaluate("st.encounter.list.find(x=>x.kind==='veh').cid");pc_cid=await gm.evaluate("st.encounter.list.find(x=>x.kind==='pc').cid")
        ok(await gm.locator(f"#cb-{vc} .veh").count()==1,"an AV-4 in the tracker")
        await gm.click("[data-act=enc-init]");await gm.wait_for_timeout(100);await gm.click("[data-act=enc-next]");await gm.click("[data-act=enc-next]");await gm.wait_for_timeout(100)
        ok(await gm.evaluate("st.encounter.list[st.encounter.turn].kind")!="veh","turns skip vehicles: they act on the driver's turn")
        await gm.select_option(f"select[data-act-change=veh-driver][data-cid='{vc}']",pc_cid);await gm.wait_for_timeout(100)
        ok("Ghost" in await gm.evaluate(f"vehChar('{vc}').drv.name"),"a runner can be the driver")
        vvid=await gm.evaluate(f"vehCb('{vc}').veh.id")
        await gm.fill(f"#vh-{vvid}","50");await gm.click(f"[data-act=veh-hit][data-v='{vvid}']");await gm.wait_for_timeout(100)
        ok(await gm.evaluate(f"vehCb('{vc}').veh.sdpDmg")==10,"50 against the AV-4's SP 40 does 10")
        await gm.click(f"[data-act=veh-control][data-v='{vvid}']");await gm.wait_for_timeout(150)
        ok("AV-4 -2" in (await gm.text_content(".modal")).replace("−","-"),"the AV-4's −2 handling on the driver's roll")
        await gm.evaluate("rig([[10,9]])");await gm.click("[data-act=vc-roll]");await gm.wait_for_timeout(120)
        ok((await gm.evaluate("Dice.log[0].label")).startswith("Simple maneuver"),"the GM rolls it for the driver")
        await gm.screenshot(path=os.path.join(SHOTS,"gm-control.png"));await gm.click("[data-act=close-modal]")
        await gm.click(f"[data-act=enc-remove][data-cid='{vc}']");await gm.wait_for_timeout(100)
        ok(not await gm.evaluate("st.encounter.list.some(x=>x.kind==='veh')"),"vehicles leave the tracker like anyone else")
        await gm.click("nav [data-act=tab][data-t=reference]");await gm.wait_for_timeout(150)
        t=await gm.text_content("main");ok(all(x in t for x in ["Vehicle control","Control modifiers","Control loss","Vehicle damage","Bootlegger"]),"the rules reference has the vehicle tables")
        print("errors:",errs);ok(not errs,"no page errors")
        await b.close()
    finish()
asyncio.run(main())
